using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using BeamScheduleFormatter;
class BeamDeflectionTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why,double tol=1e-6){Check(Math.Abs(a-b)<tol,why+" (got "+a+", expected "+b+")");}
 static void Throws(Action action,string contains,string why){try{action();}catch(Exception ex){Check(ex.Message.IndexOf(contains,StringComparison.OrdinalIgnoreCase)>=0,why+" - message was: "+ex.Message);return;}throw new Exception("Expected failure: "+why);}
 const string Nodes="Node\tX (m)\tY (m)\tZ (m)\r\n1\t0\t3\t0\r\n2\t2\t3\t0\r\n3\t4\t3\t0\r\n4\t6\t3\t0\r\n5\t0\t0\t0\r\n6\t6\t0\t0\r\n7\t8\t3\t0";
 const string Beams="Beam\tNode A\tNode B\tLength (m)\tProperty\r\n1\t1\t2\t2\t1\r\n2\t2\t3\t2\t1\r\n3\t3\t4\t2\t1\r\n4\t5\t1\t3\t2\r\n5\t6\t4\t3\t2\r\n6\t4\t7\t2\t1";
 // Supports settle 1 mm (A) and 3 mm (B); interior nodes sag. Units in mm from the heading.
 const string Disp="Node\tL/C\tX (mm)\tY (mm)\tZ (mm)\tResultant (mm)\trX (rad)\trY (rad)\trZ (rad)\r\n1\t1 DEAD\t0\t-1\t0\t1\t0\t0\t0.001\r\n\t2 LIVE\t0\t-0.5\t0\t0.5\t0\t0\t0\r\n2\t1 DEAD\t0.1\t-9\t0\t9\t0\t0\t0\r\n\t2 LIVE\t0\t-4\t0\t4\t0\t0\t0\r\n3\t1 DEAD\t0.1\t-12\t0\t12\t0\t0\t0\r\n\t2 LIVE\t0\t-6\t0\t6\t0\t0\t0\r\n4\t1 DEAD\t0\t-3\t0\t3\t0\t0\t0\r\n\t2 LIVE\t0\t-1\t0\t1\t0\t0\t0\r\n7\t1 DEAD\t0\t-10\t0\t10\t0\t0\t0\r\n\t2 LIVE\t0\t-4\t0\t4\t0\t0\t0";
 static BeamDeflectionData Data(){var d=new BeamDeflectionData();StaadDisplacements.Coordinates(d,Nodes,"mm");StaadDisplacements.Members(d,Beams);StaadDisplacements.Displacements(d,Disp,"m");return d;}
 static void Main(){
  var d=Data();Check(d.Nodes.Count==7&&d.Members.Count==6,"tables read");Check(d.GeometryUnitSource.Contains("header (m)"),"geometry unit from header overrides selected mm");Check(d.DisplacementUnitSource.Contains("header (mm)"),"displacement unit from header overrides selected m");Near(d.Nodes[4].X,6,"metres kept");Near(d.Displacements.First(x=>x.Node==3&&x.Case=="1 DEAD").Y,-0.012,"mm converted to m");Check(d.Cases().Count()==2,"two load cases with blank node continuation rows");
  const string RcFloor="RC floor not supporting or attached to nonstructural elements likely to be damaged",RcDamage="RC roof or floor supporting or attached to nonstructural elements likely to be damaged",SteelFloor="Steel or other floor member";
  Func<string,PhysicalBeamInput> beam=criterion=>new PhysicalBeamInput{Name="B1",Members="1, 2, 3",Criterion=criterion,DeadCases="1",LiveCases="2",Vertical="Y",ServiceBasis=true,SupportsVerified=true,Xi=2};
  // Chords: dead node 3 = -1 + (-3+1)*4/6 = -2.3333 -> relD = -9.6667; node 2 relD = -7.3333. Live node 3 = -6 - (-0.8333) = -5.1667; node 2 = -3.3333.
  var r=BeamDeflection.Calculate(d,beam(RcFloor));Check(r.Count==1&&r[0].Check=="Immediate live-load deflection","RC floor row 2 is one immediate live check");var live=r[0];
  Near(live.Span,6,"span across three members");Check(live.Stations.Select(s=>s.Node).SequenceEqual(new[]{1,2,3,4}),"ordered path through intermediate nodes");Near(live.Stations[2].Dead,-12+1+4.0/3,"dead relative to chord at node 3");Near(live.Stations[1].Live,-4+0.5+1.0/6,"live relative to chord at node 2");
  Near(live.MaximumMm,6-0.5-1.0/3,"live governs",1e-9);Check(live.GoverningNode==3,"governing node");Near(live.LimitMm,6000/360.0,"L/360");Check(live.Qualified&&live.Status.StartsWith("OK"),"within limit and confirmed");Near(live.Stations[0].Relative,0,"support A zero");Near(live.Stations[3].Relative,0,"support B zero");Check(live.Ratio=="L/1161","L/δ text "+live.Ratio);
  var damage=beam(RcDamage);damage.RhoPrime=.01;r=BeamDeflection.Calculate(d,damage);var after=r.Single();Near(after.Lambda,2/1.5,"λΔ = ξ/(1+50ρ')");Near(after.LimitMm,6000/480.0,"L/480");Near(after.MaximumMm,(2/1.5)*(12-1-2.0/3*2)+(6-0.5-1.0/3),"after attachment = λΔ·δD + δL",1e-9);Check(after.Exceeds&&after.Status.StartsWith("EXCEEDS"),"after-attachment check exceeds");
  damage.StiffnessFactor=2;damage.Xi=1;damage.RhoPrime=0;r=BeamDeflection.Calculate(d,damage);Near(r[0].MaximumMm,2*(12-1-4.0/3)+2*(6-0.5-1.0/3),"Ig/Ie factor applied to dead and live, ξ = 1",1e-9);
  Near(BeamDeflection.XiFor(BeamDeflection.Durations[1]),1.4,"12 months ξ");Near(BeamDeflection.Lambda(2,0),2,"λΔ without compression steel");
  r=BeamDeflection.Calculate(d,beam(SteelFloor));Check(r.Count==2&&r[0].Check=="Live-load deflection"&&r[1].Check=="Dead + live load deflection","steel floor: live and dead+live");Near(r[1].MaximumMm,(12-1-4.0/3)+(6-0.5-1.0/3),"dead + live superposed node by node",1e-9);Near(r[1].LimitMm,25,"L/240");Near(r[0].LimitMm,6000/360.0,"L/360");
  var ceiling=beam("Steel or other roof member not supporting ceiling");r=BeamDeflection.Calculate(d,ceiling);Near(r[0].LimitMm,6000/180.0,"roof no ceiling live L/180");Near(r[1].LimitMm,50,"roof no ceiling D+L L/120");
  var custom=beam(BeamDeflection.Custom);custom.CustomRatio=2000;r=BeamDeflection.Calculate(d,custom);Check(r[0].Exceeds&&r[0].LimitMm==3,"custom L/n uses the sum of listed cases");
  var explicitA=beam(RcFloor);explicitA.Members="3 2 1";explicitA.Start=4;r=BeamDeflection.Calculate(d,explicitA);Check(r[0].StartNode==4&&r[0].Stations[1].Node==3,"explicit support A reverses path");
  var unconfirmed=beam(RcFloor);unconfirmed.ServiceBasis=false;r=BeamDeflection.Calculate(d,unconfirmed);Check(!r[0].Qualified&&r[0].Status.Contains("service"),"unconfirmed load basis is REVIEW, not OK");unconfirmed.ServiceBasis=true;unconfirmed.SupportsVerified=false;r=BeamDeflection.Calculate(d,unconfirmed);Check(!r[0].Qualified&&r[0].Status.Contains("supports"),"unconfirmed supports is REVIEW");
  // Cantilever from node 4 to 7: relative to the support translation only. Steel/other uses L = 2 × cantilever length.
  var cant=beam(SteelFloor);cant.Name="C1";cant.Members="6";cant.SpanType=BeamDeflection.Cantilever;cant.Start=4;r=BeamDeflection.Calculate(d,cant);Near(r[0].MaximumMm,3,"cantilever live tip relative to root");Near(r[0].LimitMm,4000/360.0,"steel cantilever uses 2L");Near(r[1].MaximumMm,10,"cantilever dead + live");Check(r.All(x=>x.Qualified),"cantilever OK");
  var rcCant=beam(RcFloor);rcCant.Members="6";rcCant.SpanType=BeamDeflection.Cantilever;rcCant.Start=4;r=BeamDeflection.Calculate(d,rcCant);Near(r[0].LimitMm,2000/360.0,"RC cantilever uses its length");
  var single=beam(RcFloor);single.Members="6";r=BeamDeflection.Calculate(d,single);Check(r[0].Status.StartsWith("NOT CHECKED")&&!r[0].Qualified,"no interior node between supports is not checked");
  Func<Action<PhysicalBeamInput>,Action> bad=change=>()=>{var x=beam(RcDamage);change(x);BeamDeflection.Calculate(d,x);};
  Throws(bad(x=>x.Vertical="X"),"along the beam","axial component rejected");Throws(bad(x=>x.Members="1,4"),"straight","non-collinear rejected");Throws(bad(x=>x.Members="1,3"),"connected","gap rejected");
  Throws(bad(x=>x.LiveCases="9"),"not in the displacement","absent case rejected");Throws(bad(x=>x.Start=2),"not an end node","interior support rejected");Throws(bad(x=>x.Members="1,1"),"twice","duplicate member rejected");
  Throws(bad(x=>x.DeadCases=""),"dead / sustained","after-attachment check needs dead cases");Throws(bad(x=>x.LiveCases=""),"live load case","live cases required");Throws(bad(x=>x.LiveCases="1"),"both dead and live","case listed twice rejected");
  Throws(bad(x=>x.RhoPrime=.2),"ρ'","rho prime range");Throws(bad(x=>x.StiffnessFactor=.5),"Ig/Ie","Ig/Ie at least 1");Throws(bad(x=>x.Criterion="Unknown"),"criterion","unknown criterion");Throws(()=>{var x=beam(BeamDeflection.Custom);BeamDeflection.Calculate(d,x);},"custom","custom n required");
  var missing=new BeamDeflectionData();StaadDisplacements.Coordinates(missing,Nodes,"m");StaadDisplacements.Members(missing,Beams);StaadDisplacements.Displacements(missing,"Node\tL/C\tX\tY\tZ\r\n1\t1\t0\t0\t0\r\n4\t1\t0\t0\t0","mm");Throws(()=>BeamDeflection.Calculate(missing,new PhysicalBeamInput{Name="M",Members="1,2,3",Criterion=BeamDeflection.Custom,CustomRatio=360,LiveCases="1",Vertical="Y"}),"no displacement for node(s) 2, 3","missing intermediate node named");Check(missing.DisplacementUnitSource.Contains("selected unit (mm)"),"selected unit used without header units");
  Throws(()=>StaadDisplacements.Displacements(new BeamDeflectionData(),"Node\tL/C\tX (mm)\tY (m)\tZ (mm)\r\n1\t1\t0\t0\t0","mm"),"mix","mixed header units rejected");
  Throws(()=>StaadDisplacements.Displacements(new BeamDeflectionData(),"Node\tL/C\tX\tY\tZ\r\n1\t1\t0\t1,5\t0","mm"),"Invalid number","comma decimal rejected");
  var unitRow=new BeamDeflectionData();StaadDisplacements.Displacements(unitRow,"Node,L/C,X,Y,Z\r\n,,cm,cm,cm\r\n5,\"1 DL, roof\",0,-2.5,0","mm");Near(unitRow.Displacements[0].Y,-0.025,"separate unit row and quoted CSV case");Check(unitRow.Displacements[0].Case=="1 DL, roof","quoted case name kept");
  Throws(()=>{var c=new BeamDeflectionData();StaadDisplacements.Coordinates(c,"Node\tX\tY\tZ\r\n1\t0\t0\t0\r\n1\t1\t0\t0","m");},"Conflicting","conflicting node rejected");
  // STD model: UNIT MMS, continuation, semicolons, SET Z UP, supports with TO.
  string std="STAAD SPACE\r\nSTART JOB INFORMATION\r\nEND JOB INFORMATION\r\nSET Z UP\r\nUNIT MMS KN\r\nJOINT COORDINATES\r\n1 0 0 3000; 2 2000 0 3000; 3 4000 0 3000; -\r\n4 6000 0 3000;\r\n5 0 0 0; 6 6000 0 0;\r\nMEMBER INCIDENCES\r\n1 1 2; 2 2 3; 3 3 4; 4 5 1; 5 6 4;\r\nDEFINE MATERIAL START\r\nEND DEFINE MATERIAL\r\nSUPPORTS\r\n5 TO 6 FIXED\r\nFINISH\r\n";
  var model=new BeamDeflectionData();var supports=new System.Collections.Generic.HashSet<int>();StaadDisplacements.Model(model,std,"m",supports);Check(model.Nodes.Count==6&&model.Members.Count==5&&model.ZUp,"STD geometry read with continuation");Near(model.Nodes[4].X,6,"MMS converted to metres");Near(model.Nodes[1].Z,3,"Z up coordinate");Check(supports.SetEquals(new[]{5,6}),"supports TO range");Check(model.GeometryUnitSource.Contains("UNIT command (mm)"),"unit from STAAD UNIT");
  Throws(()=>StaadDisplacements.Model(new BeamDeflectionData(),"UNIT METER KN\r\nJOINT COORDINATES\r\n1 0 0 0; 2 5 0 0;\r\nREPEAT 3 0 3 0\r\n","m"),"REPEAT","REPEAT geometry rejected with guidance");
  var groups=BeamDeflection.SuggestGroups(model,"Z");Check(groups.Count==1&&groups[0].Value.OrderBy(x=>x).SequenceEqual(new[]{1,2,3}),"suggested beam line split at columns");
  var frame=Data();var lines=BeamDeflection.SuggestGroups(frame,"Y");Check(lines.Count==1&&lines[0].Value.OrderBy(x=>x).SequenceEqual(new[]{1,2,3}),"column at node 4 ends the beam line before cantilever member 6");
  // ANL: input echo with unit, page break, continuation rows, and CM heading.
  string anl="    1. STAAD SPACE\r\n    2. UNIT METER KN\r\n    3. JOINT COORDINATES\r\n    4. 1 0 3 0; 2 2 3 0; 3 4 3 0; 4 6 3 0\r\n    5. MEMBER INCIDENCES\r\n    6. 1 1 2; 2 2 3; 3 3 4\r\n    7. PRINT JOINT DISPLACEMENTS LIST 1 TO 4\r\n\r\n   JOINT DISPLACEMENT (CM   RADIANS)    STRUCTURE TYPE = SPACE\r\n   ------------------\r\n\r\n  JOINT  LOAD   X-TRANS   Y-TRANS   Z-TRANS   X-ROTAN   Y-ROTAN   Z-ROTAN\r\n\r\n      1    1    0.00000  -0.10000   0.00000   0.00000   0.00000   0.00010\r\n           2    0.00000  -0.05000   0.00000   0.00000   0.00000   0.00000\r\n      2    1    0.01000  -0.90000   0.00000   0.00000   0.00000   0.00000\r\n           2    0.00000  -0.40000   0.00000   0.00000   0.00000   0.00000\r\n STAAD SPACE                                              -- PAGE NO.    5\r\n      3    1    0.01000  -1.20000   0.00000   0.00000   0.00000   0.00000\r\n           2    0.00000  -0.60000   0.00000   0.00000   0.00000   0.00000\r\n      4    1    0.00000  -0.30000   0.00000   0.00000   0.00000   0.00000\r\n           2    0.00000  -0.10000   0.00000   0.00000   0.00000   0.00000\r\n\r\n ************** END OF LATEST ANALYSIS RESULT **************\r\n      9    1    9.0 9.0 9.0 9.0 9.0 9.0\r\n";
  var a=new BeamDeflectionData();StaadDisplacements.Anl(a,anl,"m","mm");Check(a.Nodes.Count==4&&a.Members.Count==3,"geometry from ANL echo");Check(a.Displacements.Count==8,"8 displacement rows; rows after END ignored and PRINT echo not a table");Near(a.Displacements.First(x=>x.Node==3&&x.Case=="1").Y,-0.012,"CM heading converted");Check(a.DisplacementUnitSource.Contains("heading (cm)"),"ANL unit source");
  r=BeamDeflection.Calculate(a,new PhysicalBeamInput{Name="B1",Members="1,2,3",Criterion=BeamDeflection.Custom,CustomRatio=360,DeadCases="1",Vertical="Y",ServiceBasis=true,SupportsVerified=true});Near(r[0].MaximumMm,9.6666666667,"ANL and table give the same result",1e-6);
  Throws(()=>StaadDisplacements.Anl(new BeamDeflectionData(),"no tables here","m","mm"),"PRINT JOINT DISPLACEMENTS","ANL without table gives STAAD guidance");
  // Excel import reads cached cells of each worksheet.
  string xlsx=Path.Combine(Path.GetTempPath(),"deflection-test-"+Guid.NewGuid().ToString("N")+".xlsx");try{using(var stream=File.Create(xlsx))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create)){Action<string,string> add=(name,text)=>{using(var w=new StreamWriter(zip.CreateEntry(name).Open(),new UTF8Encoding(false)))w.Write(text);};add("xl/sharedStrings.xml","<sst xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><si><t>Node</t></si><si><t>L/C</t></si><si><t>X mm</t></si><si><t>Y mm</t></si><si><t>Z mm</t></si><si><t>1 DL</t></si></sst>");add("xl/worksheets/sheet1.xml","<worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><sheetData><row r='1'><c r='A1' t='s'><v>0</v></c><c r='B1' t='s'><v>1</v></c><c r='C1' t='s'><v>2</v></c><c r='D1' t='s'><v>3</v></c><c r='E1' t='s'><v>4</v></c></row><row r='2'><c r='A2'><v>2</v></c><c r='B2' t='s'><v>5</v></c><c r='C2'><v>0</v></c><c r='D2'><v>-7.5</v></c><c r='E2'><v>0</v></c></row></sheetData></worksheet>");}
   var tables=StaadSpreadsheet.Tables(xlsx);var x=new BeamDeflectionData();StaadDisplacements.Displacements(x,tables.Values.First(),"m");Near(x.Displacements[0].Y,-0.0075,"Excel cached values with header unit");}finally{File.Delete(xlsx);}
  // Report content.
  var rcAfter=beam(RcDamage);rcAfter.Name="B2";rcAfter.RhoPrime=.01;var all=BeamDeflection.Calculate(d,beam(RcFloor)).Concat(BeamDeflection.Calculate(d,rcAfter)).Concat(BeamDeflection.Calculate(d,cant)).ToList();
  var summary=new BeamDeflectionSummary{GeometrySource="model.std",ResultSource="results.csv",GeometryUnit=d.GeometryUnitSource,DisplacementUnit=d.DisplacementUnitSource,Vertical="Y",ServiceBasis=true,SupportsVerified=true,Nodes=d.Nodes.Count,Members=d.Members.Count,Cases=d.Cases().ToList(),Duration=BeamDeflection.Durations[0]};
  string plain=BeamDeflectionReport.Text(summary,all);Check(plain.Contains("5.17")&&plain.Contains("424.2.2")&&plain.Contains("analysis nodes")&&plain.Contains("not constitute engineer approval"),"text report includes result and limitation");
  var report=BeamDeflectionReport.Create(summary,all);var titles=report.Sections.Select(s=>s.Title).ToList();Check(titles[0]=="Scope and method"&&titles.Contains("STAAD input data")&&titles.Contains("NSCP 2015 deflection criteria")&&titles.Contains("Criteria and parameters applied per beam")&&titles.Contains("Summary of checks")&&titles.Last()=="Limitations and review notes","numbered professional report sections: "+string.Join(" / ",titles));
  string html=System.Text.RegularExpressions.Regex.Replace(report.Html(),"data:image/[^'\"]+","");Check(html.Contains("<svg")&&html.Contains("5.17")&&html.Contains("424.2.4.1.1")&&html.Contains("1.333")&&!html.Contains("NaN")&&!html.Contains("Infinity"),"HTML report has figure and finite values");Check(report.Highlights.Any(h=>h.Key=="Governing δ/δallow"),"highlight of governing ratio");
  Check(BeamDeflectionReport.Svg(all[0]).Contains("polyline"),"deflected shape figure");
  // Effective moment of inertia, NSCP 2015 Section 424.2.3.5 (values checked by an independent calculation).
  var ii=new EffectiveInertiaInput{B=300,H=500,D=440,DPrime=60,As=1473,AsPrime=603,Fc=28,Ma=120};var ie=EffectiveInertia.Calculate(ii);
  Near(ie.Ec,24870.0623240,"Ec = 4700√fc'",1e-6);Near(ie.Mcr,41.0091453,"Mcr = fr Ig / yt",1e-6);Near(ie.C,144.6601501,"cracked neutral axis",1e-6);Near(ie.Icr,1366394952.097,"Icr",1);Near(ie.Ie,1436583576.641,"Ie Branson",1);Near(ie.Ratio,2.1752998,"Ig/Ie",1e-6);Near(ie.RhoPrime,603/(300.0*440),"ρ'",1e-12);
  Near(EffectiveInertia.Calculate(new EffectiveInertiaInput{B=300,H=500,D=440,DPrime=60,As=1473,AsPrime=0,Fc=28,Ma=30}).Ratio,1,"uncracked when Ma < Mcr");
  var back=EffectiveInertia.Parse(EffectiveInertia.Basis(ii));Near(back.Ma,120,"basis round trip");Throws(()=>EffectiveInertia.Calculate(new EffectiveInertiaInput{B=300,H=500,D=520,As=1000,Fc=28,Ma=50}),"Effective depth","d > h rejected");
  var withIe=beam(RcDamage);withIe.Name="B9";withIe.StiffnessFactor=ie.Ratio;withIe.RhoPrime=ie.RhoPrime;withIe.IeBasis=EffectiveInertia.Basis(ii);var ieReport=BeamDeflectionReport.Create(summary,BeamDeflection.Calculate(d,withIe));string ieHtml=ieReport.Html();Check(ieHtml.Contains("424.2.3.5")&&ieHtml.Contains("2.175")&&ieHtml.Contains("Icr = b c³/3"),"report shows the Ie derivation");
