  Check(!ProgramAccess.Allows(ProgramAccess.WindDesign,ProgramAccess.BeamDeflection),"wind access does not grant deflection sheet");
  Console.WriteLine("PASS: "+checks+" beam deflection, STAAD table/STD/ANL/Excel import, units, cantilever, grouping and report checks");}
